def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], coords: np.ndarray, demand: np.ndarray, distance_matrix: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.
    Args:
        archive: A list of tuples, where each tuple contains:
            - solution: A list of numpy arrays, each representing a vehicle route. 
                        Each route starts and ends at the depot (node index 0), e.g., [0, 3, 5, 0].
            - objective: A tuple of two float values (total_distance, makespan), 
                        representing the two objective values of the solution.

        coords: A numpy array of shape (n_nodes, 2), representing (x, y) coordinates of each node (depot + customers).
        demand: A numpy array of shape (n_nodes,), where demand[i] is the demand of node i. The depot has demand 0.
        distance_matrix: A numpy array of shape (n_nodes, n_nodes), where [i][j] is the Euclidean distance between node i and j.
        capacity: A float representing the maximum capacity of each vehicle.

    Returns:
        A new neighbor solution.
    """
    if not archive:
        raise ValueError("Archive is empty")

    archive_sorted = sorted(archive, key=lambda x: (x[1][1], -x[1][0]))
    selected_idx = min(1, len(archive_sorted) - 1)
    base_solution = archive_sorted[selected_idx][0].copy()
    new_solution = [route.copy() for route in base_solution]

    all_customers = np.unique(np.concatenate([route[1:-1] for route in new_solution]))
    if len(all_customers) == 0:
        return new_solution

    def fractal_partition(customers, depth=0, max_depth=3):
        if len(customers) <= 2 or depth >= max_depth:
            return [customers]

        customer_coords = coords[customers]
        centroid = np.mean(customer_coords, axis=0)

        left = []
        right = []
        for c in customers:
            if coords[c, 0] < centroid[0]:
                left.append(c)
            else:
                right.append(c)

        if len(left) == 0 or len(right) == 0:
            return [customers]

        return fractal_partition(left, depth+1, max_depth) + fractal_partition(right, depth+1, max_depth)

    clusters = fractal_partition(all_customers)

    new_solution = []
    for cluster in clusters:
        cluster_demand = sum(demand[cluster])
        if cluster_demand == 0:
            continue

        if cluster_demand > capacity:
            split_point = 1
            while split_point < len(cluster) and sum(demand[cluster[:split_point]]) + demand[cluster[split_point]] <= capacity:
                split_point += 1
            cluster1 = cluster[:split_point]
            cluster2 = cluster[split_point:]
            new_solution.append(np.concatenate([[0], cluster1, [0]]))
            new_solution.append(np.concatenate([[0], cluster2, [0]]))
        else:
            new_solution.append(np.concatenate([[0], cluster, [0]]))

    for i in range(len(new_solution)-1, -1, -1):
        if len(new_solution[i]) <= 2:
            new_solution.pop(i)
            continue

        route_demand = sum(demand[new_solution[i][1:-1]])
        if route_demand <= capacity * 0.7:
            for j in range(len(new_solution)):
                if i == j:
                    continue

                combined_demand = route_demand + sum(demand[new_solution[j][1:-1]])
                if combined_demand <= capacity:
                    merged_route = np.concatenate([new_solution[i][:-1], new_solution[j][1:]])
                    new_solution[j] = merged_route
                    new_solution.pop(i)
                    break

    for route in new_solution:
        if sum(demand[route[1:-1]]) > capacity:
            return base_solution

    return new_solution
